import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";import"./chunks/assets.DDNpi1qx.js";var i=JSON.parse(`{"title":"Site","description":"","frontmatter":{"prev":{"text":"Structure","link":"/documentation/structure"},"next":{"text":"Site Settings","link":"/documentation/site/site-settings"}},"headers":[],"relativePath":"documentation/site/site.md","filePath":"documentation/site/site.md","lastUpdated":1791360312000}`),a={name:`documentation/site/site.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="site" tabindex="-1">Site <a class="header-anchor" href="#site" aria-label="Permalink to “Site”">​</a></h1><p>A <strong>Site</strong> is the top-level container in Excellent Data Filler representing a web application or domain where you want to automate workflows. It acts as the central hub grouping together all related <strong>Site Forms</strong>, <strong>Segments</strong>, <strong>Excel Data Templates</strong>, <strong>Scraper Results</strong>, and <strong>Site Settings</strong>.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Sites serve as the foundational root of your automation projects:</p><ul><li><strong>Project Organization</strong>: Keeps forms, fields, and routines grouped under a dedicated domain profile.</li><li><strong>Centralized Control</strong>: Manage site-wide environment variables, column mappings, and backup configurations in one location.</li><li><strong>Multi-Page Coordination</strong>: Link multiple sequential forms and segments together using the unique Site ID.</li></ul><hr><h2 id="site-management-dashboard" tabindex="-1">Site Management Dashboard <a class="header-anchor" href="#site-management-dashboard" aria-label="Permalink to “Site Management Dashboard”">​</a></h2><p>The site management interface provides a dashboard of all registered sites:</p><img src="/image/site-01.png" alt="Site Management Interface" style="max-width:100%;border-radius:8px;margin:16px 0;"><p>Each site card displays its title, description, active status toggle, and quick-action buttons to access forms, settings, and templates.</p><hr><h2 id="insert-site" tabindex="-1">Insert Site (Auto vs. Manual Mode) <a class="header-anchor" href="#insert-site" aria-label="Permalink to “Insert Site (Auto vs. Manual Mode)”">​</a></h2><p>Excellent Data Filler provides two primary workflows for registering and configuring websites: <strong>Auto Mode</strong> (instant automated DOM scanning) and <strong>Manual Mode</strong> (granular step-by-step custom creation).</p><h3 id="overview-comparison" tabindex="-1">Overview Comparison <a class="header-anchor" href="#overview-comparison" aria-label="Permalink to “Overview Comparison”">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Auto Mode (Right-Click Context Menu)</th><th>Manual Mode (Step-by-Step Custom Setup)</th></tr></thead><tbody><tr><td><strong>Primary Action</strong></td><td>Right-click form → <strong>Insert Site</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd>)</td><td>Dashboard → <strong>Insert a new Site</strong> (<code>+</code>)</td></tr><tr><td><strong>Site Container</strong></td><td>Created automatically using current page URL</td><td>Created manually with custom title and description</td></tr><tr><td><strong>Form Page Setup</strong></td><td>Automatically generated with matched page URL</td><td>Configured manually with custom URL pattern &amp; delays</td></tr><tr><td><strong>Field Detection</strong></td><td>Automatically scans DOM tree for all form inputs</td><td>Configured manually field-by-field with chosen field types</td></tr><tr><td><strong>Element Inspection</strong></td><td>Automatic selector generation</td><td>Uses <strong>Inspect Elements</strong> and copy context helpers</td></tr><tr><td><strong>Best For</strong></td><td>Standard web forms, rapid bulk onboarding, full-form filling</td><td>Complex single-page apps, selective field filling, custom field types</td></tr></tbody></table><hr><h3 id="insert-site-auto" tabindex="-1">Method 1: Auto Mode (Context Menu &amp; Keyboard Shortcut) <a class="header-anchor" href="#insert-site-auto" aria-label="Permalink to “Method 1: Auto Mode (Context Menu &amp; Keyboard Shortcut)”">​</a></h3><p>Auto Mode is the quickest way to register a site. It extracts page metadata and scans all form inputs across the page automatically in seconds.</p><h4 id="step-by-step-instructions" tabindex="-1">Step-by-Step Instructions <a class="header-anchor" href="#step-by-step-instructions" aria-label="Permalink to “Step-by-Step Instructions”">​</a></h4><ol><li><strong>Navigate to the Target Web Page</strong>: Open the target website containing the form in your browser.</li><li><strong>Trigger Site Registration</strong>: <ul><li>Right-click anywhere inside the form area on the page and select <strong>Insert Site</strong>, or</li><li>Press the keyboard shortcut: <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd>.</li></ul></li><li><strong>Automatic Scanning &amp; Configuration</strong>: <ul><li>The extension automatically creates the root <strong>Site</strong> container.</li><li>A <strong>Site Form</strong> is generated and mapped to the target page URL.</li><li>The extension traverses the DOM tree to locate all inputs, textareas, dropdowns, checkboxes, and radio buttons.</li><li>Selectors, field types, names, and initial default values are automatically configured and saved into the extension.</li></ul></li><li><strong>Review Configuration</strong>: Open the extension dashboard to review the generated fields, adjust default values, or map fields to Excel (<code>.xlsx</code>) columns.</li></ol><div class="tip custom-block"><p class="custom-block-title">Right-Click Protected Pages</p><p>If a web page blocks right-clicking, ensure <strong>Allow Right Click?</strong> is turned ON in <img src="/svg/settings.svg" class="doc-icon" width="16" height="16" alt="Settings"> <a href="/documentation/settings.html#advanced-options">Extension Settings</a>, or use the keyboard shortcut <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd>.</p></div><hr><h3 id="insert-site-manually" tabindex="-1">Method 2: Manual Mode (Step-by-Step Custom Setup) <a class="header-anchor" href="#insert-site-manually" aria-label="Permalink to “Method 2: Manual Mode (Step-by-Step Custom Setup)”">​</a></h3><p>Manual Mode provides granular control over site containers, URL patterns, execution delays, and custom field types.</p><h4 id="step-1-create-the-site-container" tabindex="-1">Step 1: Create the Site Container <a class="header-anchor" href="#step-1-create-the-site-container" aria-label="Permalink to “Step 1: Create the Site Container”">​</a></h4><ol><li>Open the extension popup and navigate to the <strong>Sites</strong> dashboard.</li><li>Click the <strong>Insert a new Site</strong> button (<code>+</code>).</li><li>Fill in the site details: <ul><li><strong>Site Title</strong>: A descriptive name identifying the project (e.g., <code>Customer Registration Portal</code>).</li><li><strong>Site Description</strong>: Optional notes explaining the automation goal.</li><li><strong>Active Status</strong>: Enable or disable execution for this site.</li></ul></li><li>Click <strong>Save</strong> to create the site container.</li></ol><img src="/image/insert-site-manually-01.png" alt="Manual Site Creation Interface" style="max-width:480px;border-radius:8px;margin:16px 0;"><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Site Title</strong></td><td>Yes</td><td>Descriptive project name (up to 100 characters).</td></tr><tr><td><strong>Site Description</strong></td><td>No</td><td>Optional notes explaining the automation goal.</td></tr><tr><td><strong>Active Status</strong></td><td>Yes</td><td>Toggle switch to activate or pause the site.</td></tr></tbody></table><h4 id="step-2-add-a-site-form-page" tabindex="-1">Step 2: Add a Site Form Page <a class="header-anchor" href="#step-2-add-a-site-form-page" aria-label="Permalink to “Step 2: Add a Site Form Page”">​</a></h4><ol><li>Inside your newly created site, open the <strong>Site Form Pages</strong> tab.</li><li>Click <strong>Insert Form</strong> (or press <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>F</kbd> while on the target page).</li><li>Specify the form parameters: <ul><li><strong>Page URL</strong>: Enter the target form URL (e.g., <code>https://example.com/apply</code>).</li><li><strong>URL Match Type</strong>: Choose <strong>Full URL</strong>, <strong>Pathname</strong>, <strong>Hostname</strong>, or <strong>RegEx</strong>.</li><li><strong>Delays</strong>: Configure <strong>Delay Before Running</strong> (e.g., <code>500 ms</code>) to allow dynamic components to render.</li></ul></li><li>Click <strong>Save</strong> to create the form.</li></ol><h4 id="step-3-add-individual-form-fields" tabindex="-1">Step 3: Add Individual Form Fields <a class="header-anchor" href="#step-3-add-individual-form-fields" aria-label="Permalink to “Step 3: Add Individual Form Fields”">​</a></h4><ol><li>Open the form&#39;s <strong>Form Fields</strong> tab and click <strong>Insert Field</strong> (<code>+</code>).</li><li>Select the specific <strong>Field Type</strong> required for that input: <ul><li>Standard: <code>Text</code>, <code>Select</code>, <code>Radio</code>, <code>Checkbox</code>, <code>Textarea</code></li><li>Advanced: <code>Date Picker</code>, <code>Upload File</code>, <code>Button</code>, <code>JavaScript Code</code>, <code>CKEditor</code>, <code>Send Request</code></li></ul></li><li>Enter the <strong>Target Element Selector</strong> (CSS selector or XPath).</li><li>Assign the field value, dynamic variable, or Excel column header.</li><li>Save the field and repeat for any remaining inputs you wish to automate.</li></ol><hr><h3 id="context-menu-helpers" tabindex="-1">Context Menu Helpers for Manual Setup <a class="header-anchor" href="#context-menu-helpers" aria-label="Permalink to “Context Menu Helpers for Manual Setup”">​</a></h3><p>While configuring fields in Manual Mode, you do not need to inspect page source code manually. Excellent Data Filler provides integrated context menu helpers directly on the target web page (<img src="/svg/browser.svg" class="doc-icon" width="16" height="16" alt="Context Menu"> <a href="/documentation/extension/context-menu.html">Context Menu Guide</a>):</p><h4 id="interactive-element-inspection" tabindex="-1">Interactive Element Inspection <a class="header-anchor" href="#interactive-element-inspection" aria-label="Permalink to “Interactive Element Inspection”">​</a></h4><ul><li><strong>Inspect Elements</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd>): <ul><li>Right-click any element on the page and select <strong>Inspect Elements</strong>.</li><li>Opens the interactive element inspection modal to test selectors, inspect element attributes, examine bounding boxes, and confirm selector uniqueness in real time.</li></ul></li></ul><h4 id="selector-path-copy-helpers" tabindex="-1">Selector &amp; Path Copy Helpers <a class="header-anchor" href="#selector-path-copy-helpers" aria-label="Permalink to “Selector &amp; Path Copy Helpers”">​</a></h4><p>Right-click any target form input to copy its exact identifier directly to your clipboard:</p><ul><li><strong>Copy Element Selector Address</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>C</kbd>): <ul><li>Copies the optimized CSS selector for the selected element.</li><li>Paste directly into the field&#39;s <strong>Target Element Selector</strong> input.</li></ul></li><li><strong>Copy Element XPath Selector Address</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>X</kbd>): <ul><li>Copies the XPath expression of the right-clicked element.</li><li>Recommended for elements with dynamic IDs or deeply nested structures.</li></ul></li></ul><h4 id="value-text-helpers" tabindex="-1">Value &amp; Text Helpers <a class="header-anchor" href="#value-text-helpers" aria-label="Permalink to “Value &amp; Text Helpers”">​</a></h4><ul><li><strong>Copy text of selected element</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>T</kbd>): <ul><li>Copies the visible text content of the element (ideal for string matching rules or assertions).</li></ul></li><li><strong>Copy html of selected element</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>H</kbd>): <ul><li>Copies the outer HTML markup of the selected element.</li></ul></li></ul><h4 id="dropdown-select-helpers" tabindex="-1">Dropdown Select Helpers <a class="header-anchor" href="#dropdown-select-helpers" aria-label="Permalink to “Dropdown Select Helpers”">​</a></h4><p>When dealing with <code>&lt;select&gt;</code> dropdowns:</p><ul><li><strong>Copy name of selected option</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>N</kbd>): <ul><li>Copies the visible display text of a dropdown option.</li></ul></li><li><strong>Copy value of selected option</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>M</kbd>): <ul><li>Copies the underlying <code>value</code> attribute of a dropdown option.</li></ul></li><li><strong>Download select box options</strong>: <ul><li>Downloads all available options within the dropdown for reference or spreadsheet mapping.</li></ul></li></ul><h4 id="field-reusability-responses" tabindex="-1">Field Reusability &amp; Responses <a class="header-anchor" href="#field-reusability-responses" aria-label="Permalink to “Field Reusability &amp; Responses”">​</a></h4><ul><li><strong>Copy Field</strong> (<kbd>Alt</kbd> + <kbd>C</kbd>): <ul><li>Copies an entire field configuration to duplicate or reuse across multiple forms.</li></ul></li><li><strong>Copy Form Response</strong> (<kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>R</kbd>): <ul><li>Captures element text, selector, XPath, and URL to quickly construct success or error response rules.</li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">Workflow Recommendation</p><p>Use <strong>Auto Mode</strong> initially to capture all basic inputs on the page, then switch to <strong>Manual Mode</strong> techniques (using <strong>Inspect Elements</strong> and copy context helpers) to fine-tune complex selectors, add conditional delays, or configure custom field types like <code>Date Picker</code> and <code>Upload File</code>.</p></div><hr><h2 id="site-controls" tabindex="-1">Site Management Controls <a class="header-anchor" href="#site-controls" aria-label="Permalink to “Site Management Controls”">​</a></h2><p>Each site entry in the dashboard provides management actions:</p><h3 id="site-title-description" tabindex="-1">Site Title &amp; Description <a class="header-anchor" href="#site-title-description" aria-label="Permalink to “Site Title &amp; Description”">​</a></h3><ul><li><strong>Site Title</strong>: Identifies the project across extension views and export files.</li><li><strong>Site Description</strong>: Provides context for team members or future reference.</li></ul><h3 id="active-inactive-toggle" tabindex="-1">Active / Inactive Toggle <a class="header-anchor" href="#active-inactive-toggle" aria-label="Permalink to “Active / Inactive Toggle”">​</a></h3><ul><li><strong>Status Toggle</strong>: Quickly enable or pause automation for the entire site without deleting any forms, fields, or templates.</li></ul><h3 id="edit-site" tabindex="-1">Edit Site <a class="header-anchor" href="#edit-site" aria-label="Permalink to “Edit Site”">​</a></h3><ul><li>Opens the site workspace, containing tabs for: <ul><li><strong>Site Pages (Forms)</strong>: Manage target URLs and page-level automation.</li><li><strong>Segments</strong>: Build on-demand, reusable field routines.</li><li><strong>Excel Template</strong>: Download/upload <code>.xlsx</code> batch data and sync Google Sheets.</li><li><strong>Site Settings</strong>: Toggle execution flags, define site environment variables, and export backup files.</li><li><strong>Scraper Data</strong>: Inspect and export extracted page data.</li></ul></li></ul><h3 id="duplicate-site" tabindex="-1">Duplicate Site <a class="header-anchor" href="#duplicate-site" aria-label="Permalink to “Duplicate Site”">​</a></h3><ul><li>Creates an instant clone of the site, including all configured forms, segments, fields, and timing rules. Useful for staging vs. production environments.</li></ul><h3 id="copy-site-id" tabindex="-1">Copy Site ID <a class="header-anchor" href="#copy-site-id" aria-label="Permalink to “Copy Site ID”">​</a></h3><ul><li>Copies the unique internal alphanumeric ID for this site to your clipboard.</li><li><strong>Use Case</strong>: When browsing to subsequent pages of a multi-step form, press <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>F</kbd> (or select <strong>Insert Form</strong> from the context menu) and paste the Site ID to link the new page to this site.</li></ul><h3 id="delete-site" tabindex="-1">Delete Site <a class="header-anchor" href="#delete-site" aria-label="Permalink to “Delete Site”">​</a></h3><ul><li>Permanently removes the site container and all associated forms, segments, and field configurations.</li><li><strong>Recommendation</strong>: Export a site backup via <a href="/documentation/site/site-settings.html#export-site-data">Site Settings</a> before performing permanent deletions.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="site-not-created-from-context-menu" tabindex="-1">Site Not Created from Context Menu <a class="header-anchor" href="#site-not-created-from-context-menu" aria-label="Permalink to “Site Not Created from Context Menu”">​</a></h3><ul><li><strong>Extension Disabled</strong>: Verify that the extension is toggled <strong>ON</strong> in the browser toolbar.</li><li><strong>Restricted Pages</strong>: Browser extensions cannot execute on internal pages (such as <code>chrome://</code> or <code>edge://</code>) or web store listings.</li><li><strong>Right-Click Blocked</strong>: If the page prevents context menus via JavaScript, use the shortcut <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd> or enable <strong>Allow Right Click?</strong> in <a href="/documentation/settings.html#advanced-options">Settings</a>.</li><li><strong>Diagnostics</strong>: Check the built-in <a href="/documentation/logs.html">Logs</a> dashboard for execution details.</li></ul><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/site/site-settings.html">Site Settings</a> — Configure execution toggles, site environment variables, and exports</li><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form/form.html#insert-site-form">Insert Site Form</a> — Add form pages and URL matching rules</li><li><img src="/svg/system.svg" class="doc-icon"> <a href="/documentation/segment.html">Segments</a> — Build on-demand, reusable field routines</li><li><img src="/svg/code.svg" class="doc-icon"> <a href="/documentation/form-fields/field.html#insert-field">Form Fields Configuration</a> — Set up individual form field selectors</li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template Management</a> — Download and upload <code>.xlsx</code> spreadsheets</li></ul>`,71)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};